// Initialize 16 random oscillators
let oscillators = Array(16).fill(0).map(() => ({
  phase: Math.random() * 2 * Math.PI,
  frequency: 1.0
}));

const K = 0.6180339887498948482; // PHI_INV
const dt = 0.873; // HEARTBEAT_MS/1000

// Run 100 heartbeat cycles
for (let i = 0; i < 100; i++) {
  oscillators = await julia.kuramocoStep(oscillators, K, dt);
}

const R = await julia.orderParameter(oscillators);
console.log('Order parameter R:', R); // Should be > 0.618
